cd specs/sk-doc/066-skill-readability-refinement/002-cli-external-orchestration/006-cli-hermes/scratch && python3 - <<'PY'
import json
for name in ['review-1.md.json','review-2.md.json','review-3.md.json']:
    print('='*20, name)
    rows=[]
    for line in open(name):
        line=line.strip()
        if not line: continue
        try: rows.append(json.loads(line))
        except: pass
    # find text parts
    texts=[]
    for r in rows:
        p=r.get('part') if isinstance(r,dict) else None
        if isinstance(p,dict) and p.get('type')=='text' and p.get('text'):
            texts.append(p['text'])
    for t in texts[-2:]:
        print(t[:4000])
        print('---')
PY

